fn longest(strings: Vec<Vec<char>>) -> Option<Vec<char>> {
    // Turn the input into an iterator over owned Vec<char>
    let mut iter = strings.into_iter();

    // If the list is empty, return None
    let mut best = match iter.next() {
        Some(s) => s,
        None => return None,
    };

    // For each remaining sequence, if it's strictly longer than `best`,
    // replace `best`. Ties are ignored so that we keep the earliest max.
    for s in iter {
        if s.len() > best.len() {
            best = s;
        }
    }

    Some(best)
}

